<?php
/* Caminho: pages/atendimentos.php */
declare(strict_types=1);
require dirname(__DIR__).'/includes/bootstrap.php';$pdo=arc_db();arc_ensure_user_schema($pdo);
if(!arc_is_user()&&!arc_is_admin()){header('Location: '.arc_workspace_base_url().'index.php',true,303);exit;}
$admin=arc_is_admin();$uid=(int)arc_user_id();$where=$admin?'1=1':'(n.account_id=? OR EXISTS (SELECT 1 FROM '.arc_table('network_team_members').' m WHERE m.account_id=n.account_id AND m.network_id=n.id AND m.member_user_id=? AND m.enabled=1))';$params=$admin?[]:[$uid,$uid];
$q=$pdo->prepare('SELECT n.id,n.name,n.account_id,COUNT(t.id) AS tickets,SUM(t.status IN (\'open\',\'in_progress\',\'waiting\')) AS active_count,SUM(t.status NOT IN (\'resolved\',\'cancelled\') AND t.due_at<NOW()) AS overdue FROM '.arc_table('managed_networks').' n LEFT JOIN '.arc_table('support_tickets').' t ON t.network_id=n.id AND t.account_id=n.account_id WHERE '.$where.' GROUP BY n.id,n.name,n.account_id ORDER BY overdue DESC,active_count DESC,n.name LIMIT 200');$q->execute($params);$networks=$q->fetchAll();
$q=$pdo->prepare('SELECT u.display_name,COUNT(DISTINCT t.id) AS tickets,COUNT(DISTINCT CASE WHEN e.event_type=\'resolved\' THEN t.id END) AS resolved,COALESCE(SUM(e.minutes_spent),0) AS minutes FROM '.arc_table('support_events').' e JOIN '.arc_table('support_tickets').' t ON t.id=e.ticket_id JOIN '.arc_table('managed_networks').' n ON n.id=t.network_id AND n.account_id=t.account_id LEFT JOIN '.arc_table('user_accounts').' u ON u.id=e.actor_id WHERE '.$where.' AND e.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY e.actor_id,u.display_name ORDER BY minutes DESC,tickets DESC LIMIT 100');$q->execute($params);$team=$q->fetchAll();
$q=$pdo->prepare('SELECT s.command_id,s.network_id,s.ticket_id,s.created_at,u.display_name,n.name,c.status,c.completed_at FROM '.arc_table('support_remote_sessions').' s JOIN '.arc_table('managed_networks').' n ON n.id=s.network_id AND n.account_id=s.account_id JOIN '.arc_table('agent_commands').' c ON c.id=s.command_id LEFT JOIN '.arc_table('user_accounts').' u ON u.id=s.technician_id WHERE '.$where.' ORDER BY s.command_id DESC LIMIT 50');$q->execute($params);$sessions=$q->fetchAll();
$ARCPageTitle='Atendimentos e equipe';$ARCActiveNav='support_center';require dirname(__DIR__).'/includes/header.php';require dirname(__DIR__).'/includes/sidebar.php';
?>
<main class="app-main"><div class="page-content arc-service"><header class="arc-service-heading"><div><h1>Atendimentos e equipe</h1><p>Filas por rede, produtividade e rastreabilidade dos acessos remotos.</p></div><?php if(!$admin):?><a class="button" href="api/download-support.php" aria-label="Aplicativo Windows" title="Aplicativo Windows"><i class="fa fa-arrow-right" aria-hidden="true"></i><span class="arc-action-label">Aplicativo Windows</span></a><?php endif;?></header><div class="arc-service-metrics"><article><small>Chamados registrados</small><strong><?=array_sum(array_column($networks,'tickets'))?></strong></article><article><small>Em aberto</small><strong><?=array_sum(array_column($networks,'active_count'))?></strong></article><article><small>Prazo excedido</small><strong><?=array_sum(array_column($networks,'overdue'))?></strong></article></div>
<section class="arc-service-card"><h2>Operações por rede</h2><div class="arc-service-list"><?php foreach($networks as $n):?><article><div><strong><?=arc_h($n['name'])?></strong><p><?=(int)$n['active_count']?> em aberto · <?=(int)$n['overdue']?> fora do prazo</p></div><?php if(!$admin):?><a class="button" href="redes/chamados.php?network=<?=(int)$n['id']?>" aria-label="Abrir chamados" title="Abrir chamados"><i class="fa fa-arrow-right" aria-hidden="true"></i><span class="arc-action-label">Abrir chamados</span></a><?php endif;?></article><?php endforeach;?><?php if(!$networks):?><p>Nenhuma rede disponível.</p><?php endif;?></div></section>
<section class="arc-service-card"><h2>Equipe · participações nos últimos 30 dias</h2><span class="arc-page-help"><button type="button" class="arc-icon-action" data-open-dialog="page-help-1" aria-label="Saiba mais sobre esta área" title="Saiba mais"><i class="fa fa-info" aria-hidden="true"></i></button></span><dialog id="page-help-1" class="arc-service-dialog"><header class="arc-service-heading"><h2>Saiba mais</h2><button type="button" class="arc-icon-action" data-close-dialog aria-label="Fechar"><i class="fa fa-times" aria-hidden="true"></i></button></header><p>Os tempos são registros manuais de trabalho; não representam monitoramento oculto de técnicos.</p></dialog><div class="arc-service-list"><?php foreach($team as $t):?><article><strong><?=arc_h($t['display_name']?:'Sem responsável')?></strong><span><?=(int)$t['tickets']?> chamados com participação · <?=(int)$t['resolved']?> resolvidos · <?=(int)$t['minutes']?> minutos registrados</span></article><?php endforeach;?><?php if(!$team):?><p>Sem atendimentos no período.</p><?php endif;?></div></section>
<section class="arc-service-card"><h2>Últimas sessões remotas</h2><div class="arc-service-list"><?php foreach($sessions as $s):?><article><div><strong>#<?=(int)$s['command_id']?> · <?=arc_h($s['name'])?></strong><p><?=arc_h($s['display_name']?:'Técnico')?> · <?=arc_h($s['status'])?> · <?=arc_h(arc_when($s['created_at']))?><?=$s['ticket_id']?' · chamado #'.(int)$s['ticket_id']:''?></p></div></article><?php endforeach;?><?php if(!$sessions):?><p>Nenhuma sessão registrada.</p><?php endif;?></div></section></div></main><?php require dirname(__DIR__).'/includes/footer.php';?>
